delete from lab_has_hazards haz
where haz.id_lab_has_hazards in (select lhh.id_lab_has_hazards from hazard_form hf
    inner join hazard_form_history hfh on hf.id_hazard_form = hfh.id_hazard_form
    inner join hazard_category hc on hc.id_hazard_category =hf.id_hazard_category
    inner join lab_has_hazards lhh on lhh.id_hazard_form_history = hfh.id_hazard_form_history
    where hc.id_hazard_category = 34)
